const stopWords = new Set([
  "que","por","para","como","cual","cuales","cuanto","cuantos","donde","cuando","quien","quienes","hay","una","uno","unos","unas","del","los","las","con","sin","sobre","esta","este","son","es","the","what","why","how","which","where","when","who","does","are","is","and","from","into","about","with","without","this","that"
]);

function normalize(text = "") {
  return text.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9\s]/g, " ").replace(/\s+/g, " ").trim();
}

function keywordsFrom(question) {
  return [...new Set(normalize(question).split(" ").filter((word) => word.length > 2 && !stopWords.has(word)))].slice(0, 7);
}

function variants(question, language) {
  const clean = question.replace(/[¿?]/g, "").trim();
  if (language === "es") {
    const lower = clean.charAt(0).toLowerCase() + clean.slice(1);
    return [question, `NOVA, ${lower}?`, `Explícame ${lower}.`, `Quiero saber ${lower}.`];
  }
  const lower = clean.charAt(0).toLowerCase() + clean.slice(1);
  return [question, `NOVA, ${lower}?`, `Explain ${lower}.`, `I want to know ${lower}.`];
}

function entry(id, topic, esQuestion, enQuestion, esAnswer, enAnswer) {
  return {
    id,
    topic,
    level: "explorador",
    keywords: { es: keywordsFrom(esQuestion), en: keywordsFrom(enQuestion) },
    questions: { es: variants(esQuestion, "es"), en: variants(enQuestion, "en") },
    answer: { es: esAnswer, en: enAnswer },
  };
}

